import{z as s,x as B,o as r,c as p,q as i,j as n,D as t,d as E,s as l,S as A,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"MM 与公司税盾","description":"","frontmatter":{"title":"MM 与公司税盾","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/mm-corporate-tax.md","filePath":"econ/mm-corporate-tax.md","lastUpdated":1791413859000}'),D={name:"econ/mm-corporate-tax.md"};function d(_,a,c,m,u,C){const o=B("Mermaid");return r(),p("div",null,[a[2]||(a[2]=i('<h1 id="mm-与公司税盾" tabindex="-1">MM 与公司税盾 <a class="header-anchor" href="#mm-与公司税盾" aria-label="Permalink to &quot;MM 与公司税盾&quot;">​</a></h1><div class="epigraph"><p>利息在公司税前扣除，股利不；家庭不能自制这一不对称，切片开始改变饼的大小。</p><footer>—— Modigliani and Miller, Corporate Income Taxes and the Cost of Capital: A Correction, American Economic Review 1963</footer></div><p>定位：<a href="/econ/modigliani-miller">上一课</a>。1958 年的套利已经证明：无税、无破产成本时，总价值与债股切片无关，\\(r_A\\) 才是资金成本。本课缺口是把公司所得税放回去——1963 年更正的那一块。不重做家庭自制杠杆，不把破产成本提前写成内部最优。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>1958 年论文把税对债与股当作对称，或干脆抽掉。美国（以及多数）公司税允许利息在应税所得里扣除，股利在公司层面不扣。多一单位永久债务，每期少交 \\(\\tau_c r_D\\)，若折现率就是 \\(r_D\\)，税盾现值是 \\(\\tau_c D\\)。杠杆企业价值变成</p> \\[V_L = V_U + \\tau_c D. \\]<p>若只有这一块摩擦，最优是角点：百分之百债务。这与观察到的内部股权冲突，也与银行资本监管冲突。缺口是先把税盾的会计写对，并标明角点；抵消项是下一课<a href="/econ/tradeoff-capital">权衡</a>的工作。</p><p><span class="marginnote">家庭自制杠杆复制的是资产收益流，复制不了「企业少交的那笔税」。税盾是付给企业的转移，不是付给自制杠杆的家庭。</span></p><p><span class="marginnote">数字实例：公司税率 \\(\\tau_c=25\\%\\)，永久借入 1 亿、利率 5%。每年利息 500 万，全部税前扣除，每年少缴税 125 万；这笔现金流永久，按 5% 折现，现值 \\(=125/0.05=2500\\) 万，恰等于 \\(\\tau_c D=0.25\\times 1\\) 亿。公式 \\(\\tau_c D\\) 就是这么来的——「每借一块钱，政府白送两毛五的税盾」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>1963 年的论证仍是套利加税法，不是问卷调查。无杠杆企业的现金流在税后是 \\((1-\\tau_c)X\\)；杠杆企业是 \\((1-\\tau_c)(X-r_D D)+r_D D = (1-\\tau_c)X + \\tau_c r_D D\\)。多出来的 \\(\\tau_c r_D D\\) 是政府少收的。若债务无风险且永久滚动、税率不变，其现值即 \\(\\tau_c D\\)，加在 \\(V_U\\) 上。</p><p>命题 II 随之改写：股权成本仍随杠杆上升，但加权平均资本成本随债务下降，因为权重里有一块税后债务成本 \\(r_D(1-\\tau_c)\\)。1958 年「不要用 \\(r_E\\gt r_D\\) 去论证应当借债」仍然成立；1963 年允许的是另一句：<strong>税后</strong> WACC 可以随 \\(D\\) 下降。下降来自税，不是来自「债务便宜」。</p>',12)),(r(),n(A,null,{default:t(()=>[l(o,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20MM58%5B%221958%3A%20VL%20%3D%20VU%22%5D%20--%3E%20TAX%5B%22%E5%85%AC%E5%8F%B8%E7%A8%8E%3A%20%E5%88%A9%E6%81%AF%E5%8F%AF%E6%89%A3%22%5D%0A%20%20TAX%20--%3E%20SHIELD%5B%22%E7%A8%8E%E7%9B%BE%E7%8E%B0%E5%80%BC%22%5D%0A%20%20SHIELD%20--%3E%20VL%5B%22VL%20%3D%20VU%20%2B%20Tc%20D%22%5D%0A%20%20VL%20--%3E%20CORNER%5B%22%E4%BB%85%E6%9C%89%E7%A8%8E%3A%20%E8%A7%92%E7%82%B9%20100%25%20%E5%80%BA%22%5D%0A%20%20CORNER%20--%3E%20NEXT%5B%22%E4%B8%8B%E4%B8%80%E8%AF%BE%3A%20%E5%8A%A0%E5%9B%B0%E5%A2%83%E6%88%90%E6%9C%AC%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"个人所得税若对利息课得比对股权收益更重，会吃掉公司税盾。Miller（1977）后来把这写成客户与加总税率。本课停在公司税这一层，以免把更正写成完整的税制史。",-1)),a[4]||(a[4]=e("p",null,[e("span",{class:"marginnote"},"「WACC（加权平均资本成本）」翻译成大白话：把债主要求的回报和股东要求的回报，按各自市值权重加权平均——$ \\mathrm{WACC}=(D/V),r_D(1-\\tau_c)+(E/V),r_E$。注意债务成本打了 \\((1-\\tau_c)\\) 的折：5% 的借款在 \\(\\tau_c=25\\%\\) 时真实成本只有 3.75%，省下的 1.25 个百分点就是税盾在折现率侧的影子。")],-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,"机制是复制失败的第一块。完全市场上投资者能自制杠杆，不能自制法人所得税的扣除项。企业多发行债务，等于把政府对利息的补贴写进证券；这块补贴随切片变，所以 \\(V\\) 随切片变。Arrow–Debreu 价格仍给状态定价，但可交易的支付已经包含税后转移，税后支付的集合随资本结构变。",-1)),(r(),n(A,null,{default:t(()=>[l(o,{id:"mermaid-45",class:"mermaid",graph:"flowchart%20LR%0A%20%20A1%5B%22%E6%8A%95%E8%B5%84%E8%80%85%E8%87%AA%E5%88%B6%E6%9D%A0%E6%9D%86%EF%BC%9A%E8%87%AA%E5%B7%B1%E5%80%9F%E9%92%B1%E4%B9%B0%E6%97%A0%E6%9D%A0%E6%9D%86%E8%82%A1%22%5D%20--%3E%20A2%5B%22%E5%A4%8D%E5%88%B6%E5%87%BA%E5%90%8C%E6%A0%B7%E7%9A%84%E7%A8%8E%E5%89%8D%E6%94%B6%E7%9B%8A%E6%B5%81%22%5D%0A%20%20A2%20--%3E%20A3%5B%22V%20%E4%B8%8E%E5%88%87%E7%89%87%E6%97%A0%E5%85%B3%EF%BC%881958%EF%BC%89%22%5D%0A%20%20B1%5B%22%E4%BC%81%E4%B8%9A%E5%80%9F%E5%80%BA%EF%BC%9A%E5%88%A9%E6%81%AF%E7%A8%8E%E5%89%8D%E6%89%A3%E9%99%A4%22%5D%20--%3E%20B2%5B%22%E6%94%BF%E5%BA%9C%E6%AF%8F%E6%9C%9F%E5%B0%91%E6%94%B6%20%CF%84c%C2%B7rD%C2%B7D%22%5D%0A%20%20B2%20--%3E%20B3%5B%22%E5%AE%B6%E5%BA%AD%E5%A4%8D%E5%88%B6%E4%B8%8D%E4%BA%86%E8%BF%99%E7%AC%94%E8%BD%AC%E7%A7%BB%22%5D%0A%20%20B3%20--%3E%20B4%5B%22V_L%20%3D%20V_U%20%2B%20%CF%84c%C2%B7D%EF%BC%881963%EF%BC%89%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=i('<p><span class="marginnote">常见误区：以为散户「自己借钱炒股」也能享受同样的抵税。利息扣除发生在<strong>公司应税所得</strong>那一层，是法人身份证才刷得开的门；家庭借钱炒股走的是个人税制，抵扣范围完全不同。复制得了收益流、复制不了税，这正是 1963 年与 1958 年的分水岭。</span></p><p>银行版本刺耳之处依旧：存款利息也可扣，税盾偏向杠杆；<a href="/econ/deposit-insurance">存款保险</a>再降低私人看到的下行。税盾不是监管资本的反对理由，它只说明：无摩擦基准一旦加入税法，私人最优就会往债的方向走。监管切一刀是因为外部性，不是因为税务局算错了。</p><h3 id="不是不可错的公式" tabindex="-1">\\(\\tau_c D\\) 不是不可错的公式 <a class="header-anchor" href="#不是不可错的公式" aria-label="Permalink to &quot;$\\tau_c D$ 不是不可错的公式&quot;">​</a></h3><p>亏损无法立即抵扣、利息抵扣上限、债务并非无风险永久，都会使税盾现值小于 \\(\\tau_c D\\)。1963 年更正给的是基准会计，不是估税软件。把某家企业的法定税率乘上账面债务，当成已经实现的 \\(V\\) 增量，会把后课权衡的左边估大。</p><p><span class="marginnote">股利税与资本利得税在股东层面还会再切一刀。本课对象是公司税不对称。Miller–Modigliani 1961 的股利无关性是另一篇，不要在这里重开派息。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把 1963 年读成「应当尽量借债」的政策结论：缺了破产与代理，角点只是逻辑提示——还必须有抵消项。也不要把 1958 年命题 I 说成已被更正推翻：无税世界的无关性仍在；有税世界换了一条加法。</p><p>本课不估计破产成本，不写 Kraus–Litzenberger 的状态偏好权衡。下一课才把税盾对困境成本收成内部 \\(D^\\ast\\)。也不要把 \\(\\tau_c D\\) 当成银行资本「昂贵」的完整解释：保险、流动性服务同样破坏复制。</p><p>后课默认：公司税使 \\(V_L=V_U+\\mathrm{PV}(\\text{税盾})\\)，仅有税则角点在全债。权衡从这里起步。不要在权衡课里再推一遍 1963 年的税后现金流分解。</p><p>WACC 随杠杆下降，下降来自 \\(\\tau_c\\)，不是来自「债务要求回报低」。命题 II 的斜率仍在。</p><p>家庭不能自制税盾。这是 1958 年复制条件里最先被拿掉的一块。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>1963 年更正：利息可扣，税盾进入 \\(V\\)；仅有税则全债最优。</li><li>税后 WACC 可随 \\(D\\) 下降；「债务便宜所以加杠杆」仍不是 1958 年的逻辑。</li><li>复制失败因为家庭造不出公司税。</li><li>出处：Modigliani and Miller, <em>AER</em> 1963。</li></ul>',13))])}const V=s(D,[["render",d]]);export{f as __pageData,V as default};
